/* X DNA — void black, ghost grays, one blue, ruthless density */
.theme-x-dna {
  --bg: oklch(0.000 0 0);
  --surface: oklch(0.209 0.009 264.4);
  --surface-2: oklch(0.255 0.009 255.6);
  --fg: oklch(0.933 0.003 228.8);
  --fg-muted: oklch(0.563 0.010 248.0);
  --accent: oklch(0.961 0.004 214.3);
  --accent-fg: oklch(0.188 0.013 248.5);
  --accent-2: oklch(0.667 0.161 245.5);
  --line: oklch(0.318 0.008 240.1);
  --success: oklch(0.696 0.156 160.6);
  --warning: oklch(0.881 0.181 94.0);
  --danger: oklch(0.619 0.238 25.8);
  --radius: 1rem;
  --radius-sm: 0.5rem;
  --radius-lg: 1.25rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Schibsted Grotesk", sans-serif;
  --font-body: "Schibsted Grotesk", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: -0.02em;
  --label-transform: none;
  --label-tracking: 0.04em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-x-dna h1,
.theme-x-dna h2,
.theme-x-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-x-dna { --font-ui: var(--font-display); }
.theme-x-dna h1 { font-weight: 800; letter-spacing: -0.04em; }
.theme-x-dna button { font-weight: 700; }
.theme-x-dna a, .theme-x-dna .text-accent { color: #1d9bf0; }

/* alt mode: auto-derived light variant */
.theme-x-dna.alt-mode {
  --bg: oklch(0.98 0.000 0.0);
  --surface: oklch(0.955 0.000 0.0);
  --surface-2: oklch(0.92 0.000 0.0);
  --fg: oklch(0.17 0.005 270);
  --fg-muted: oklch(0.46 0.01 270);
  --line: oklch(0.87 0.005 270);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --accent: oklch(0.52 0.080 214.3);
  --accent-fg: oklch(1 0 0);
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
